## Testing Done

I wrote this unit test to verify functionality but didn't include it since it's build code.  Unsure of where tests would go for that.

```kotlin
class MembershipTest {
    @Test
    fun `it handles defined memberships`() {
        val unit = parseMembership("+a, +b, -c")

        assertTrue(unit.isMember("a"))
        assertTrue(unit.isMember("b"))
        assertFalse(unit.isMember("c"))
        assertFalse(unit.isMember("f"))
        assertFalse(unit.isMember(""))
    }

    @Test
    fun `it handles implicit memberships`() {
        val unit = parseMembership("-a, -b,-c")

        assertFalse(unit.isMember("a"))
        assertFalse(unit.isMember("b"))
        assertFalse(unit.isMember("c"))
        assertTrue(unit.isMember("f"))
        assertTrue(unit.isMember(""))
    }

    @Test
    fun `it handles conflicts`() {
        Assertions.assertThrows(IllegalArgumentException::class.java) {
            parseMembership("-a,    +a")
        }
    }
}
```

